      "detailsOdia": "ଏହି ଐତିହାସିକ କାଳଖଣ୍ଡରେ କୃଷି, ବାଣିଜ୍ୟ, ନଗରୀକରଣ ଏବଂ ସାମାଜିକ ସଂଗଠନରେ ଉଲ୍ଲେଖନୀୟ ପରିବର୍ତ୍ତନ ଘଟିଥିଲା। ଗ୍ରାମୀଣ ପଞ୍ଚାୟତ ବ୍ୟବସ୍ଥା, କର ନୀତି, ଶିଳ୍ପ ବିକାଶ ଏବଂ ସାମୁଦ୍ରିକ ତଥା ସ୍ଥଳ ବାଣିଜ୍ୟ ପଥ ମାଧ୍ୟମରେ ଓଡ଼ିଶାର ଅର୍ଥନୀତି ଦୃଢ଼ୀଭୂତ ହୋଇଥିଲା। ବିଭିନ୍ନ ଶ୍ରେଣୀର କାରିଗର, ସାଧବ ଓ କୃଷକମାନେ ରାଷ୍ଟ୍ର ନିର୍ମାଣରେ ପ୍ରମୁଖ ଭାଗିଦାର ଥିଲେ।"
