      "detailsOdia": "ଶଙ୍ଖ କ୍ଷେତ୍ର (ପୁରୀ), ଚକ୍ର କ୍ଷେତ୍ର (ଭୁବନେଶ୍ୱର), ପଦ୍ମ କ୍ଷେତ୍ର (କୋଣାର୍କ) ଓ ଗଦା କ୍ଷେତ୍ର (ଯାଜପୁର)।\n\nଏହି ଐତିହାସିକ ପ୍ରସଙ୍ଗରେ ଡ. ହରେକୃଷ୍ଣ ମହତାବ, ପ୍ରଫେସର ନବୀନ କୁମାର ସାହୁ, କେଦାରନାଥ ମହାପାତ୍ର ଏବଂ ଡ. ଅଞ୍ଜନ କୁମାର ପାଲଙ୍କ ଗବେଷଣା ଅନୁଯାୟୀ, ଓଡ଼ିଶାର ରାଜନୈତିକ, ସାମାଜିକ ଓ ସାଂସ୍କୃତିକ ଧାରାରେ ଏହା ଏକ ଯୁଗାନ୍ତକାରୀ ଭୂମିକା ଗ୍ରହଣ କରିଥିଲା। ପ୍ରାଥମିକ ପ୍ରତ୍ନତାତ୍ତ୍ୱିକ ସାକ୍ଷ୍ୟ, ଅଭିଲେଖାଗାର ନଥିପତ୍ର, ଏପିଗ୍ରାଫିଆ ଇଣ୍ଡିକା (Epigraphia Indica) ଓ ରାଜକୀୟ ତାମ୍ରଶାସନରୁ ଏହାର ନିର୍ଭୁଲ ତଥ୍ୟ ପ୍ରମାଣିତ ହୋଇଛି।"
