      "detailsOdia": "୬ଟି ଜିଲ୍ଲା ବିଶିଷ୍ଟ ପ୍ରଥମ ଭାଷାଭିତ୍ତିକ ପ୍ରଦେଶର ନକଲ।\n\nଏହି ଐତିହାସିକ ପ୍ରସଙ୍ଗରେ ଡ. ହରେକୃଷ୍ଣ ମହତାବ, ପ୍ରଫେସର ନବୀନ କୁମାର ସାହୁ, କେଦାରନାଥ ମହାପାତ୍ର ଏବଂ ଡ. ଅଞ୍ଜନ କୁମାର ପାଲଙ୍କ ଗବେଷଣା ଅନୁଯାୟୀ, ଓଡ଼ିଶାର ରାଜନୈତିକ, ସାମାଜିକ ଓ ସାଂସ୍କୃତିକ ଧାରାରେ ଏହା ଏକ ଯୁଗାନ୍ତକାରୀ ଭୂମିକା ଗ୍ରହଣ କରିଥିଲା। ପ୍ରାଥମିକ ପ୍ରତ୍ନତାତ୍ତ୍ୱିକ ସାକ୍ଷ୍ୟ, ଅଭିଲେଖାଗାର ନଥିପତ୍ର, ଏପିଗ୍ରାଫିଆ ଇଣ୍ଡିକା (Epigraphia Indica) ଓ ରାଜକୀୟ ତାମ୍ରଶାସନରୁ ଏହାର ନିର୍ଭୁଲ ତଥ୍ୟ ପ୍ରମାଣିତ ହୋଇଛି।"
